// IANAtunnelType is the SMI enum IANAtunnelType.
// The encapsulation method used by a tunnel. The value direct indicates
// that a packet is encapsulated directly within a normal IP header, with
// no intermediate header, and unicast to the remote tunnel endpoint (e.g.,
// an RFC 2003 IP-in-IP tunnel, or an RFC 1933 IPv6-in-IPv4 tunnel). The
// value minimal indicates that a Minimal Forwarding Header (RFC 2004) is
// inserted between the outer header and the payload packet. The value UDP
// indicates that the payload packet is encapsulated within a normal UDP
// packet (e.g., RFC 1234). The values sixToFour, sixOverFour, and isatap
// indicates that an IPv6 packet is encapsulated directly within an IPv4
// header, with no intermediate header, and unicast to the destination
// determined by the 6to4, 6over4, or ISATAP protocol. The remaining
// protocol-specific values indicate that a header of the protocol of that
// name is inserted between the outer header and the payload header. The IP
// Tunnel MIB [RFC4087] is designed to manage tunnels of any type over IPv4
// and IPv6 networks; therefore, it already supports IP-in-IP tunnels. But
// in a DS-Lite scenario, the tunnel type is point-to-multipoint IP-in-IP
// tunnels. The direct(2) defined in the IP Tunnel MIB only supports
// point-to-point tunnels. So, it needs to define a new tunnel type for
// DS-Lite. The assignment policy for IANAtunnelType values is identical to
// the policy for assigning IANAifType values.
type IANAtunnelType int32

const (
	IANAtunnelTypeOther        IANAtunnelType = 1
	IANAtunnelTypeDirect       IANAtunnelType = 2
	IANAtunnelTypeGre          IANAtunnelType = 3
	IANAtunnelTypeMinimal      IANAtunnelType = 4
	IANAtunnelTypeL2tp         IANAtunnelType = 5
	IANAtunnelTypePptp         IANAtunnelType = 6
	IANAtunnelTypeL2f          IANAtunnelType = 7
	IANAtunnelTypeUdp          IANAtunnelType = 8
	IANAtunnelTypeAtmp         IANAtunnelType = 9
	IANAtunnelTypeMsdp         IANAtunnelType = 10
	IANAtunnelTypeSixToFour    IANAtunnelType = 11
	IANAtunnelTypeSixOverFour  IANAtunnelType = 12
	IANAtunnelTypeIsatap       IANAtunnelType = 13
	IANAtunnelTypeTeredo       IANAtunnelType = 14
	IANAtunnelTypeIpHttps      IANAtunnelType = 15
	IANAtunnelTypeSoftwireMesh IANAtunnelType = 16
	IANAtunnelTypeDsLite       IANAtunnelType = 17
	IANAtunnelTypeAplusp       IANAtunnelType = 18
)

func (v IANAtunnelType) String() string {
	switch v {
	case IANAtunnelTypeOther:
		return "other"
	case IANAtunnelTypeDirect:
		return "direct"
	case IANAtunnelTypeGre:
		return "gre"
	case IANAtunnelTypeMinimal:
		return "minimal"
	case IANAtunnelTypeL2tp:
		return "l2tp"
	case IANAtunnelTypePptp:
		return "pptp"
	case IANAtunnelTypeL2f:
		return "l2f"
	case IANAtunnelTypeUdp:
		return "udp"
	case IANAtunnelTypeAtmp:
		return "atmp"
	case IANAtunnelTypeMsdp:
		return "msdp"
	case IANAtunnelTypeSixToFour:
		return "sixToFour"
	case IANAtunnelTypeSixOverFour:
		return "sixOverFour"
	case IANAtunnelTypeIsatap:
		return "isatap"
	case IANAtunnelTypeTeredo:
		return "teredo"
	case IANAtunnelTypeIpHttps:
		return "ipHttps"
	case IANAtunnelTypeSoftwireMesh:
		return "softwireMesh"
	case IANAtunnelTypeDsLite:
		return "dsLite"
	case IANAtunnelTypeAplusp:
		return "aplusp"
	}

	return fmt.Sprintf("IANAtunnelType(%d)", v)
}
